insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('65656cd5-dc90-497e-9903-06cf9c500e07', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$inleiding: kunsthartkleppen groeien niet mee$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context1.png$$,
   $$In Nederland worden jaarlijks ongeveer vijfduizend hartkleppen vervangen door kunsthartkleppen. Bij kinderen met een kunsthartklep, moet de klep meerdere keren worden vervangen, omdat een kunsthartklep niet meegroeit. Biomedisch ingenieur Carlijn Bouten werkt aan een oplossing voor dit probleem.$$, 'inline'),
  ('f4bc8703-fea4-4077-806c-f3044ba923ce', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$kader: vier hartkleppen (afbeelding 1)$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context2.png$$,
   $$In het hart zijn vier kleppen aanwezig:
− twee slagaderkleppen (afbeelding 1, Q en R)
− twee kleppen tussen de boezems en kamers (afbeelding 1, P en S)
afbeelding 1: doorsnede van het hart met de vier kleppen aangegeven met P, Q, R en S$$, 'inline'),
  ('9fd060a1-bdeb-4f19-9017-85f1b402f7aa', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$twee mogelijke afwijkingen van de aortaklep$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context3.png$$,
   $$Twee mogelijke hartafwijkingen zijn:
1 De aortaklep is te stug en opent daardoor niet goed.
2 De aortaklep is te slap en sluit daardoor niet goed.$$, 'inline'),
  ('66efe03c-98cb-4fc2-8813-f8f46b551e94', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$minder bloed naar de organen geeft vermoeidheid$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context4.png$$,
   $$Als er minder bloed naar de organen stroomt, ontstaat eerder vermoeidheid door een gebrek aan energie.$$, 'inline'),
  ('25f22e76-41e9-4ad6-a49a-f99edfb28484', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$kader: biologisch afbreekbare slagaderklep (afbeelding 2)$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context5.png$$,
   $$Bouten heeft een slagaderklep ontwikkeld van een biologisch afbreekbare kunststof (afbeelding 2). Na de implantatie worden tussen de kunstvezels van de slagaderklep witte bloedcellen en bindweefselcellen ingevangen. Tegen de tijd dat de bindweefselcellen voldoende stevige en elastische eiwitten (collageen en elastine) hebben aangemaakt, wordt de kunststof afgebroken.
afbeelding 2: foto van de kunststof slagaderklep met een vergroting van het netwerk van kunstvezels$$, 'inline'),
  ('f4f774ef-d4a2-4405-ad2e-66745115d53b', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$bloedstolling door een geïmplanteerde kunstklep$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context6.png$$,
   $$Het grote probleem bij een geïmplanteerde kunstklep is dat het materiaal bloedstolling veroorzaakt.$$, 'inline'),
  ('fbd82da7-c72d-408d-b5e2-efcbc6ccf558', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$kader: test van de kunstklep onder omstandigheden in de longslagader$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context7.png$$,
   $$Het functioneren van de kunstklep is in het laboratorium getest in een kunstslagader onder de omstandigheden die heersen in een longslagader. In plaats van bloed werd een zoutoplossing door de kunstklep heen gepompt.$$, 'inline'),
  ('3388a2ce-7690-4512-bcee-1948be507ad8', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$foto's van één hartcyclus$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context8.png$$,
   $$In afbeelding 3 zijn foto’s te zien van een filmpje van het functioneren van de kunstklep als longslagaderklep. De foto’s beslaan één hartcyclus, waarvan de drie achtereenvolgende perioden zijn aangegeven met letters.$$, 'inline'),
  ('b4c8fd31-9410-4aae-9dc2-2813dc129821', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$afbeelding 3: kunstklep tijdens perioden P, Q en R$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context9.png$$,
   $$afbeelding 3: zeven foto''s van de kunstklep tijdens één hartcyclus, verdeeld over drie achtereenvolgende perioden P, Q en R; in P en R is de klep gesloten, in Q is de klep (gedeeltelijk) geopend$$, 'inline'),
  ('3de67c82-1210-4763-97b4-ea840f09365b', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$drie fasen van de hartcyclus$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context10.png$$,
   $$De drie fasen van de hartcyclus zijn:
− hartpauze
− samentrekken boezems
− samentrekken kamers$$, 'inline'),
  ('dfbc3646-6486-49fb-a9a0-c31a9d86d35a', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$test onder omstandigheden in de aorta$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context11.png$$,
   $$Na de test onder de omstandigheden die heersen in de longslagader, is de kunstklep getest onder de omstandigheden die heersen in de aorta.$$, 'inline'),
  ('8c7f6e52-fda9-47bd-8450-b7aff923d762', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$kader: fasen van de geïmplanteerde klep bij schapen (afbeelding 4)$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context12.png$$,
   $$Na de succesvolle tests in het laboratorium is de kunstklep bij schapen geïmplanteerd op de plaats van de longslagaderklep. Gedurende een jaar werd de gezondheid van deze schapen gecontroleerd. Uit dit onderzoek blijkt dat het weefsel van de geïmplanteerde klep verschillende fasen doorloopt om uiteindelijk een ''levende'' klep te worden (afbeelding 4).
afbeelding 4: schema van de fasen: kunstvezels → ontstekingsfase → groeifase → ontwikkelingsfase → levend weefsel. Legenda: witte bloedcel, endotheelcel, bindweefselcel$$, 'inline'),
  ('286e3399-b437-48a1-81e1-93623bdfe3fa', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$witte bloedcellen veroorzaken een ontstekingsreactie$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context13.png$$,
   $$De eerste cellen die het kunstvezelnetwerk van de kunstklep binnendringen, zijn witte bloedcellen die in weefsels op zoek zijn naar lichaamsvreemde stoffen. Deze cellen veroorzaken in de kunstklep een ontstekingsreactie.$$, 'inline'),
  ('b912f61e-6f8a-4ec2-b543-7b68c95f85a9', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$groeifase: stamcellen; drie uitspraken$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context14.png$$,
   $$Tijdens de groeifase komen verschillende stamcellen het kunstvezelnetwerk binnen vanuit het bloed en het omringende hartweefsel van het schaap. Gestimuleerd door de ontsteking gaan deze stamcellen zich delen om nieuwe cellen (bindweefsel- en endotheelcellen) te vormen. Over de groeifase worden de volgende uitspraken gedaan:
1 Uit één stamcel ontstaat na mitose één endotheelcel en één bindweefselcel.
2 Een endotheelcel krijgt zijn vorm en functie door celdifferentiatie.
3 Celdifferentiatie wordt bepaald door veranderingen in genexpressie.$$, 'inline'),
  ('199e7600-e25a-4144-b03b-05e21b6a6451', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', $$ontwikkelingsfase: kunstvezelresten in een blaasje$$,
   $$biologie-havo-2024-i-een-nieuwe-hartklep-door-het-lichaam-zelf-gemaakt-context15.png$$,
   $$Tijdens de ontwikkelingsfase worden de kunstvezels afgebroken, zodat uiteindelijk alleen hartklepcellen overblijven in een netwerk van stevige en elastische eiwitten. De restanten van de kunstvezels worden opgeruimd door witte bloedcellen die deze restanten opnemen in een blaasje. Dit blaasje versmelt vervolgens met een bepaald celorganel, zodat de kunststofrestanten verteerd kunnen worden.$$, 'inline'),
  ('eff6bf4b-feee-4068-ae70-bec0b1d975f8', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$inleiding: foto's van tuinslakken met de app SnailSnap$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context1.png$$,
   $$Met de app SnailSnap op hun telefoon maken Dylan en Senna foto’s van slakken rond hun huis. Zo doen ze mee aan een onderzoek naar de verspreiding en evolutie van kleurvormen van de gewone tuinslak.$$, 'inline'),
  ('b6742e66-e0e5-40b4-8d01-5adf664c38f5', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$kader: kleur en streping van het slakkenhuis; SnailSnap en de hypothese (afbeelding 1 en 2)$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context2.png$$,
   $$De kleur van het huisje van de tuinslak (Cepaea nemoralis) kan geel, bruin of roze zijn. Het huisje kan gestreept of niet gestreept zijn (afbeelding 1).
afbeelding 1: foto''s van een gele slak zonder strepen en een gele slak met strepen
De kleur en streping van het slakkenhuis zijn erfelijk bepaald.
SnailSnap stuurt de foto samen met de gps-coördinaten naar waarneming.nl (afbeelding 2). Vervolgens wordt de foto beoordeeld door een deskundige. Als het inderdaad een foto van een tuinslak is, noteert de deskundige de kleur en de streping van het huisje. Deze gegevens worden samen met de gps-coördinaten opgestuurd naar Naturalis Biodiversity Center in Leiden.
Onderzoekers van Naturalis willen de hypothese toetsen dat slakken met een geel huisje (gele slakken) vaker vóórkomen in een stedelijke omgeving dan in een landelijke omgeving.
afbeelding 2: schermafbeelding van de app SnailSnap 1.0.4$$, 'inline'),
  ('e152a5b0-6052-4141-9b68-a21b943d4f33', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$drie allelen voor de kleur van het huisje$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context3.png$$,
   $$De kleur van het huisje wordt bepaald door één gen waarvan drie allelen bekend zijn. Het allel Cᵇ (bruin) is dominant over Cʳ (roze). Beide zijn dominant over cᵍ (geel).$$, 'inline'),
  ('13e0df5f-e31b-4b81-a757-24ac626b87df', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$infographic van 8000 waarnemingen$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context4.png$$,
   $$Niels Kerstes, onderzoeker van Naturalis, heeft de gegevens van 8000 waarnemingen in 2017 verwerkt in een infographic (afbeelding 3).$$, 'inline'),
  ('247d7890-8131-4d84-b03d-d7b1d690a8e9', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$afbeelding 3: infographic kleur en strepen in landelijke en stedelijke omgeving$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context5.png$$,
   $$afbeelding 3: infographic met twee gestapelde staven (aandeel 0 tot 1,0) voor de landelijke en de stedelijke omgeving, per kleur verdeeld in slakken met strepen (grijs) en zonder strepen (wit). Afgelezen (ongeveer): landelijke omgeving: geel 0–0,50, roze 0,50–0,80, bruin 0,80–1,0; stedelijke omgeving: geel 0–0,55, roze 0,55–0,80, bruin 0,80–1,0. Binnen elke kleur is het grootste deel gestreept. Een aparte staaf ''strepen'' laat zien dat ongeveer 0,75 van alle slakken strepen heeft en ongeveer 0,25 geen strepen.$$, 'inline'),
  ('3094e019-c941-4673-8956-f82a478bc0c9', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$drie uitspraken over de infographic$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context6.png$$,
   $$Dylan en Senna bekijken de infographic en doen de volgende uitspraken:
1 In een stedelijke omgeving is een groter aandeel slakken met strepen waargenomen dan in een landelijke omgeving.
2 Er zijn ongeveer 1600 bruine slakken waargenomen met SnailSnap.
3 Uit de infographic blijkt dat in de stedelijke omgeving ongeveer evenveel slakken zijn waargenomen als in de landelijke omgeving.$$, 'inline'),
  ('53949585-0d3e-472c-8cf5-bfa14d436c5c', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$kader: meer gele slakken in de stad; gele huisjes warmen minder op$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context7.png$$,
   $$Zoals Kerstes verwachtte, worden in een stedelijke omgeving relatief meer gele slakken waargenomen dan in een landelijke omgeving. Het temperatuurverschil tussen een stedelijke en een landelijke omgeving kan oplopen tot 7 °C. De gele huisjes hebben de lichtste kleur en zullen daardoor meer licht weerkaatsen, en dus minder opwarmen.$$, 'inline'),
  ('863d2ecb-f21b-48d8-b270-0030063d3440', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$toename van het aandeel gele slakken door klimaatverandering$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context8.png$$,
   $$Kerstes verwacht dat door de temperatuurstijging als gevolg van klimaatverandering het aandeel gele slakken in de populatie zal toenemen. Over de toename van het aandeel gele slakken wordt de volgende uitspraak gedaan: De temperatuurstijging veroorzaakt …(1)… waardoor de …(2)… van gele slakken toeneemt ten opzichte van roze en bruine slakken.$$, 'inline'),
  ('eb4329af-382b-4431-8106-0b9df0dfe8c8', '9f413499-8bd7-4d5a-b2b3-90163ebc4dd6', $$persoonlijkheid van slakken; hypothese stad versus platteland$$,
   $$biologie-havo-2024-i-op-jacht-met-snailsnap-context9.png$$,
   $$Dylan en Senna vragen zich af of er nog andere verschillen zijn tussen tuinslakken in een stedelijke en in een landelijke omgeving. Ze lezen over een methode waarmee je de ‘persoonlijkheid’ van de slakken kan onderzoeken: Als je een slak oppakt, trekt hij zich terug in zijn huisje. Leg je de slak vervolgens rustig neer, dan zal hij na enige tijd weer uit zijn huisje kruipen. De tijd tussen terugtrekken en uitkruipen is een maat voor de persoonlijkheid van de slak. Dylan en Senna denken dat tuinslakken uit een stedelijke omgeving sneller weer uit hun huisje zullen kruipen dan die uit een landelijke omgeving.$$, 'inline'),
  ('9d3baa52-3e1b-49b3-8270-1a56ff3c7312', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$inleiding: jeukende bultjes door brandharen (afbeelding 1 en 2)$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context1.png$$,
   $$Geert komt thuis van een schoolkamp met op zijn borst en armen rode bultjes die erg jeuken. De bultjes zijn veroorzaakt door brandharen van eikenprocessierupsen.
afbeelding 1: foto van eikenprocessierupsen op een tak
afbeelding 2: microscoopfoto van een brandhaar met weerhaakjes, vergroting 500 x$$, 'inline'),
  ('b08e7b83-e63f-4934-ad26-26ea48c9e4c1', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$eikenprocessierups eet eikenbladeren; witte haren en brandharen$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context2.png$$,
   $$De eikenprocessierups (afbeelding 1) is de larve van de nachtvlinder Thaumetopoea processionea. De rupsen leven in eiken, waar ze van de bladeren eten. Het lichaam van de eikenprocessierups is bedekt met lange witte haren, met daartussen korte, zwarte brandharen.$$, 'inline'),
  ('37099335-1cbc-4f25-a487-10a9d2543422', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$brandharen laten los; toename sinds 1990$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context3.png$$,
   $$Eén rups kan 700.000 brandharen hebben. Als de rupsen of de nesten waarin ze zich bevinden worden verstoord, laten de brandharen los. Een brandhaar (afbeelding 2) kan bij de mens een hevig jeukend bultje veroorzaken.Sinds 1990 is het aantal eikenprocessierupsen sterk toegenomen. Dit komt mogelijk door klimaatverandering, door een afname in de biodiversiteit of door een combinatie hiervan.$$, 'inline'),
  ('20494f97-6702-40ec-92ac-b8350b8e67f9', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$tabel: vlinders met brandharen en de habitat van hun rupsen$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context4.png$$,
   $$Er zijn meerdere vlinders waarvan de rupsen brandharen hebben die huidirritatie kunnen veroorzaken. In de tabel staan de wetenschappelijke naam van een aantal van deze vlinders en de habitat van hun rupsen.
tabel (wetenschappelijke naam | habitat)
Thaumetopoea processionea processionea | eikenbomen
Thaumetopoea processionea pseudosolitaria | eikenbomen
Thaumetopoea pityocampa | dennenbomen
Euproctis chrysorrhoea | duindoornstruiken en eikenbomen$$, 'inline'),
  ('de091827-2258-4635-a8dc-0d8e94bc5a45', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$details vanaf 0,1 mm zichtbaar met het blote oog$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context5.png$$,
   $$Zonder een vergrootglas zijn details vanaf een grootte van 0,1 mm meestal te zien. Een brandhaar van de eikenprocessierups (afbeelding 2) is langer dan 0,1 mm, maar is toch niet te zien met het blote oog.$$, 'inline'),
  ('84e06ab4-1a5e-47ad-8eaa-ab5cf2a95c2b', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$kader: thaumetopoïne veroorzaakt bultjes, jeuk en krabreflex$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context6.png$$,
   $$De losgelaten brandharen worden door de wind verspreid en kunnen zo in contact komen met de huid en de kleding van mensen. De brandharen maken piepkleine wondjes in de huid, waarbij het eiwit thaumetopoïne vrijkomt. Dit giftige eiwit veroorzaakt de afgifte van stoffen in de huid die bultjes veroorzaken. Ook prikkelen deze stoffen de uiteinden van gevoels- zenuwcellen, waardoor jeuk ontstaat en een krabreflex kan volgen.$$, 'inline'),
  ('95cff0b8-2223-4d48-8cb8-85279a6f3909', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$kleren wassen bij 60 °C of in de vriezer bij –20 °C$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context7.png$$,
   $$De brandharen zitten ook in de kleren die Geert tijdens het kamp gedragen heeft. Door de kleine weerhaakjes zijn de brandharen moeilijk te verwijderen. Om de brandharen onschadelijk te maken, wil Geert de kleren wassen bij 60 °C. Geerts vader stelt voor om de kleren een nacht in de vriezer (–20 °C) te leggen.$$, 'inline'),
  ('495a34a6-75ff-429a-8f14-391b8f22e94f', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$afname van biodiversiteit als oorzaak$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context8.png$$,
   $$Een mogelijke oorzaak van de toegenomen aantallen eikenprocessierupsen is de afname van de biodiversiteit.$$, 'inline'),
  ('779c9f88-3d70-4edd-912e-60ba05cb3a24', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$aangevreten eiken produceren kleinere eikels$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context9.png$$,
   $$Eiken die zijn aangevreten door eikenprocessierupsen produceren kleinere eikels dan vergelijkbare eiken zonder rupsen.$$, 'inline'),
  ('4b3dc8be-82ea-41a6-b3bf-1b05e4ab192e', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$bestrijding met nematoden en hun bacteriën$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context10.png$$,
   $$Geert wil weten of de eikenprocessierups bestreden kan worden. Hij vindt op internet dat er diverse mogelijkheden zijn. Een mogelijkheid is het bespuiten van besmette eiken met microscopisch kleine wormpjes: nematoden. De nematoden dringen dan de eikenprocessierupsen binnen die op de bespoten eiken zitten. In de darm van een nematode leven bacteriën. Als de nematode een rups is binnengedrongen, geeft de nematode de bacteriën af. Die scheiden vervolgens enzymen uit, waardoor de rups van binnenuit verteerd wordt. De verteringsproducten die daarbij ontstaan, worden gegeten door de nematode. Op grond van deze gegevens blijkt er sprake te zijn van symbiose tussen de nematode en de bacterie.$$, 'inline'),
  ('30cc36e5-85a1-4f9a-92f0-aff971d21ddf', '726be110-69c6-49ae-83c4-0ec7c1ff83c2', $$chemische bestrijding; persistente middelen$$,
   $$biologie-havo-2024-i-last-van-de-eikenprocessierups-context11.png$$,
   $$Geert leest dat de eikenprocessierups ook chemisch bestreden kan worden. Chemische bestrijdingsmiddelen hebben echter als nadeel dat ze vaak persistent zijn.$$, 'inline'),
  ('2b462926-a1c8-4903-bd3c-35bf83196b4e', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$inleiding: Emma (17) nog nooit ongesteld geweest$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context1.png$$,
   $$Emma is 17 jaar en heeft zich altijd een meisje gevoeld. Ze is echter nog nooit ongesteld geworden en heeft ook nauwelijks borstontwikkeling. Daarom gaat ze naar de huisarts.$$, 'inline'),
  ('fc1fba3f-f17b-4005-98b0-17e5957cfa6c', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$kader: echoscopie en karyogram van Emma (afbeelding 1)$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context2.png$$,
   $$Emma krijgt een echoscopie. Op de echo is te zien dat ze wel een baarmoeder en eileiders heeft, maar geen eierstokken. De doktersassistent neemt bloed af bij Emma zodat in het laboratorium een karyogram gemaakt kan worden. In afbeelding 1 zie je het karyogram van Emma.
afbeelding 1: karyogram met de chromosoomparen 1 tot en met 22 en de geslachtschromosomen Y en X$$, 'inline'),
  ('4512f79a-9e5d-42d6-b03a-0a35ea4dc56d', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$definitie karyotype$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context3.png$$,
   $$Het karyotype beschrijft per lichaamscel het totale aantal chromosomen, de geslachtschromosomen en eventuele extra chromosomen.$$, 'inline'),
  ('97c917eb-d88b-4a0d-9cbd-51bbcf19040d', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$afwijkende oestradiol- en FSH-concentratie; regulatieschema (afbeelding 2)$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context4.png$$,
   $$De huisarts laat het bloed van Emma ook onderzoeken op de aanwezigheid van geslachtshormonen. De concentraties van oestradiol (oestrogeen) en FSH in Emma''s bloed blijken sterk af te wijken van de gemiddelde waarden voor vrouwen van dezelfde leeftijd: de concentratie oestradiol in haar bloed is lager en de concentratie FSH in haar bloed is hoger.
In afbeelding 2 is de regulatie van de productie van oestradiol en FSH schematisch weergegeven.
afbeelding 2: schema: hypothalamus → GnRH (+) → hypofyse → FSH (+) en LH (+) → eierstok → oestradiol; oestradiol remt (−) de hypothalamus en de hypofyse$$, 'inline'),
  ('39e61aa1-9c8a-4e70-9150-49de4360d9fd', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$kader: SRY-gen niet werkzaam; uitleg over de aanleg van geslachtsorganen$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context5.png$$,
   $$De huisarts vermoedt dat Emma het syndroom van Swyer heeft. Vervolgonderzoek door een klinisch-genetisch arts bevestigt dit: door een mutatie is bij Emma het SRY-gen niet werkzaam. Normaal gesproken beïnvloedt dit gen, dat zich op het Y-chromosoom bevindt, de ontwikkeling van de geslachtsorganen. De arts legt uit: “In de eerste weken van de embryonale ontwikkeling verloopt de aanleg van de geslachtsorganen van een jongen en een meisje hetzelfde: er worden oer-geslachtsklieren aangelegd. Als er geen SRY-gen aanwezig is, dan ontwikkelen deze oerklieren zich verder tot eierstokken. Is er wel een functionerend SRY-gen aanwezig, dan wordt vanaf de zesde week het SRY-eiwit gevormd, dat ervoor zorgt dat zaadballen worden aangelegd. Deze zaadballen gaan de hormonen testosteron en AMH vormen. Testosteron stimuleert de ontwikkeling van de bijballen en zaadleiders en andere mannelijke primaire geslachtskenmerken. AMH zorgt voor het verdwijnen van de aanleg van de vrouwelijke geslachtsorganen. Bij jou, Emma, is het SRY-gen wel aanwezig, maar door een mutatie kwam het niet tot expressie.”$$, 'inline'),
  ('89bd8bca-bd0f-4db8-9c24-a70aa28a50e2', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$vier gevolgen van de mutatie en vier organisatieniveaus$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context6.png$$,
   $$De mutatie van het SRY-gen van Emma heeft gevolgen op verschillende organisatieniveaus. Vier gevolgen zijn:
1 Er is sprake van onvruchtbaarheid.
2 Er ontwikkelen zich geen bijballen en zaadleiders.
3 Er vindt geen ontwikkeling plaats van testosteron-producerende cellen.
4 Er wordt geen SRY-eiwit gevormd.
Vier organisatieniveaus zijn: P celniveau Q molecuulniveau R orgaanniveau S organismeniveau$$, 'inline'),
  ('f417025c-5d45-4af6-9f32-ba2e1da7cdc9', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$drie uitspraken over de mutatie in het SRY-gen$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context7.png$$,
   $$Over de mutatie die leidt tot het niet-werkzame SRY-gen worden de volgende uitspraken gedaan:
1 De mutatie kan zijn ontstaan bij de vorming van een zaadcel.
2 Het is een genoommutatie.
3 Een persoon met mannelijke primaire geslachtskenmerken kan drager zijn van de mutatie.$$, 'inline'),
  ('d58aaec1-5740-4670-b729-791b273ec6d1', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$kader: pillen met oestradiol$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context8.png$$,
   $$Emma zou graag een vrouwelijker uiterlijk krijgen. Om haar borstontwikkeling te stimuleren krijgt ze daarom pillen met oestradiol.$$, 'inline'),
  ('80040c1d-d0c7-43fd-9bb0-06d66f065558', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$oestradiol van de darm naar de borstslagader; negen bloedvaten$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context9.png$$,
   $$De oestradiolmoleculen worden geresorbeerd in de darm en bereiken het borstweefsel via een borstslagader. Een aantal bloedvaten zijn:
1 aorta
2 bovenste holle ader
3 darmslagader
4 leverader
5 leverslagader
6 longader
7 longslagader
8 onderste holle ader
9 poortader$$, 'inline'),
  ('5718a0cd-4af1-4802-a782-5df309c1022c', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$genexpressie door oestradiol; processen P t/m T (afbeelding 3)$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context10.png$$,
   $$Oestradiol leidt tot genexpressie in cellen van Emma''s borstweefsel. Hierbij vinden de volgende processen plaats:
P binding van een hormoon aan een hormoonreceptor
Q eiwit-vouwing in het cytoplasma
R transport naar de kern
S vorming van een keten van aminozuren aan de ribosomen
T vorming van RNA
Deze processen zijn met nummers weergegeven in afbeelding 3.
afbeelding 3: schematische tekening van een cel waarin oestradiol de cel binnengaat; de processen zijn genummerd 1 tot en met 5: 1 bij de binding van oestradiol in het cytoplasma, 2 bij de pijl naar de kern, 3 bij het DNA in de kern, 4 bij een streng buiten de kern en 5 bij een gevouwen keten$$, 'inline'),
  ('5e54bcce-28b8-4336-9328-a4a65658ee60', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$kader: oestradiol wordt uitgescheiden via urine en ontlasting$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context11.png$$,
   $$Emma moet de oestradiolpillen dagelijks slikken, omdat het grootste deel van het oestradiol binnen enkele dagen na opname wordt uitgescheiden. Oestradiol komt dan terecht in de urine en in de ontlasting.$$, 'inline'),
  ('07bd0dfd-9d0e-4713-84b5-841832b5af5a', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$oestradiol in de voorurine en terugresorptie$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context12.png$$,
   $$In de nieren komt oestradiol in de voorurine terecht. Daarna wordt in het eerste gekronkelde nierbuisje een deel van het oestradiol gereabsorbeerd.$$, 'inline'),
  ('f10acf0d-4116-45ec-8cdf-53c4e2fe7832', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$oestradiol uitgescheiden zoals cholesterol$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context13.png$$,
   $$Oestradiol komt terecht in de ontlasting, omdat een deel op dezelfde manier als cholesterol wordt uitgescheiden.$$, 'inline'),
  ('4648289e-0cbf-4791-9248-f86c3d414eca', 'da1fd813-a5e4-4557-b1da-96d0ad5960e9', $$eiceldonatie en ivf met hormooninjecties$$,
   $$biologie-havo-2024-i-het-syndroom-van-swyer-context14.png$$,
   $$Emma vraagt aan de arts of ze later kinderen kan krijgen. Die vertelt haar dat ze misschien via eiceldonatie en ivf zwanger kan worden. De eiceldonor krijgt dan hormooninjecties toegediend, waardoor er meerdere eicellen gaan rijpen. Emma zal dan hormooninjecties toegediend krijgen die haar baarmoeder voorbereiden op de innesteling van een embryo.$$, 'inline'),
  ('a570549e-6f1a-4493-a580-41df2263438d', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$inleiding: Charles hoorde stemmen; schizofrenie in de familie$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context1.png$$,
   $$Charles heeft tweemaal meegemaakt dat hij stemmen hoorde die er niet waren. Hij is bang dat hij aan schizofrenie lijdt, een ziekte die meerdere van zijn familieleden hebben.$$, 'inline'),
  ('3a097794-93e9-4dac-862f-7c9788852171', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$kader: schizofrenie en psychoses; tabel kans op schizofrenie per situatie$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context2.png$$,
   $$De psychische aandoening schizofrenie is een ziekte waarbij iemands denken en waarnemen ernstig zijn verstoord. Een kenmerk van schizofrenie is het optreden van psychoses, waarbij iemand dingen waarneemt die er niet zijn. Maar niet iedereen die een psychose doormaakt, heeft schizofrenie. De precieze oorzaak van schizofrenie is nog niet bekend. Wel is duidelijk dat er een of meerdere erfelijke factoren een rol spelen. Als een familielid schizofrenie heeft, is de kans op het ontwikkelen van schizofrenie groter. In de tabel is voor vijf verschillende situaties weergegeven hoe groot de kans is dat iemand de aandoening ontwikkelt.
tabel (situatie | familielid met schizofrenie | kans op het ontwikkelen van schizofrenie)
1 | geen | 1%
2 | neef of nicht | 3%
3 | broer of zus | 9%
4 | tweelingbroer of -zus; twee-eiig | 14%
5 | tweelingbroer of -zus; eeneiig | 50%$$, 'inline'),
  ('7044dc65-1577-4990-be64-0e6974f0b005', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$invloed van milieu-omstandigheden in de baarmoeder$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context3.png$$,
   $$De gegevens in de tabel doen vermoeden dat, behalve genetische factoren, ook de milieu-omstandigheden in de baarmoeder of rondom de bevalling invloed hebben op de kans op schizofrenie.$$, 'inline'),
  ('ee8e43cf-40a9-4cd9-902d-7c56b2f27951', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$symptomen van een psychose$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context4.png$$,
   $$Een veelvoorkomend symptoom van een psychose is het waarnemen van stemmen die er niet zijn. Ook kan het zijn dat beelden, geuren of smaken die er niet zijn, waargenomen worden. Uit deze symptomen is af te leiden dat tijdens een psychose processen verstoord zijn in een bepaald deel van het centraal zenuwstelsel.$$, 'inline'),
  ('4ac9eb82-c897-40ac-8e78-aaa5ac704d79', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$kader: antistof tegen de receptor van een neurotransmitter$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context5.png$$,
   $$De Australische onderzoeker Fabienne Brilot onderzocht het afweersysteem van jongeren met psychoses. Bij 19% van deze jongeren vond zij in het bloed een antistof tegen de receptor voor een bepaalde neurotransmitter. Hieruit concludeerde Brilot dat deze jongeren een auto- immuunziekte hebben: hun afweersysteem richt zich tegen een lichaamseigen stof.$$, 'inline'),
  ('fc1171f4-56a3-4f3e-8a3c-2948d2223b07', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$afbeelding van een synaps met onderdelen P t/m S$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context6.png$$,
   $$In de afbeelding is een synaps weergegeven. Vier onderdelen zijn met letters aangegeven.
afbeelding: tekening van een synaps met blaasjes en mitochondriën in het uiteinde van de presynaptische zenuwcel; P wijst een blaasje met neurotransmitter aan, Q het presynaptisch membraan, R de neurotransmitter in de synapsspleet en S de receptoren in het postsynaptisch membraan
De antistof tegen de receptor voor de neurotransmitter verstoort de impulsoverdracht.$$, 'inline'),
  ('2c384fb5-ec90-478e-9e8d-d140cbea0885', 'a66eb226-df2b-442a-98c4-979ad3213c00', $$bloedonderzoek naar de auto-immuunziekte$$,
   $$biologie-havo-2024-i-psychose-door-auto-immuunreactie-context7.png$$,
   $$Charles leest dat het onderzoek van Brilot in samenwerking met de universiteit van Maastricht wordt uitgebreid. Voor dit onderzoek worden proefpersonen gezocht. Charles besluit contact op te nemen. Na een intake door een psychiater wordt een bloedmonster van Charles onderzocht in een laboratorium. In het laboratorium voegt een laborant een bepaalde stof toe aan het bloedmonster om de auto-immuunziekte te kunnen vaststellen.$$, 'inline'),
  ('83c9d23c-2b72-4db1-a21d-2fbbaef9e458', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$inleiding: Anouk gaat quinoa telen$$,
   $$biologie-havo-2024-i-quinoa-context1.png$$,
   $$Anouk heeft tuinbouw en akkerbouw aan de HAS Hogeschool gestudeerd. Tijdens haar stage in Peru heeft ze kennisgemaakt met de teelt van quinoa. Als ze na haar studie het akkerbouwbedrijf van haar ouders overneemt, besluit ze ook quinoa te gaan telen.$$, 'inline'),
  ('f57a2aca-ff14-453d-b4ca-c82d2179a536', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$kader: quinoa, een tolerant gewas (afbeelding 1)$$,
   $$biologie-havo-2024-i-quinoa-context2.png$$,
   $$Quinoa (Chenopodium quinoa, afbeelding 1) is een gewas dat al eeuwen geteeld wordt in Bolivia en Peru. De plant vormt grote trossen met kleine eetbare zaadjes die een hoge voedingswaarde hebben. Quinoa is een zeer tolerant gewas, vooral wat droogte betreft. Het verdraagt zowel hoge temperaturen als nachtvorst, en kan ook op verzilte bodems groeien.
afbeelding 1: tekening van een quinoaplant met trossen en een hoopje zaadjes$$, 'inline'),
  ('49009308-89bc-4934-a0a5-578e8ecdddac', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$veganistische levenswijze$$,
   $$biologie-havo-2024-i-quinoa-context3.png$$,
   $$Anouk vindt dat in de toekomst zowel de manier van voedsel produceren als de manier van voedsel consumeren zal moeten veranderen om de groeiende wereldbevolking van voedsel te kunnen voorzien. Zelf is ze veganist geworden en eet dus geen dierlijke producten zoals vlees, vis, eieren en zuivelproducten.$$, 'inline'),
  ('a9a35f93-c552-4cf7-9249-0dc457c6dc22', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$veganisme en het gebruik van landbouwgrond$$,
   $$biologie-havo-2024-i-quinoa-context4.png$$,
   $$Een veganistische levenswijze heeft invloed op het gebruik van landbouwgrond. Voor het voeden van een groep mensen met een veganistische levenswijze is minder landbouwgrond nodig dan voor een even grote groep mensen die wel dierlijke producten eten.$$, 'inline'),
  ('7a18ae01-dcb0-41f4-bb99-aad32ee566e8', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$essentiële aminozuren in quinoa$$,
   $$biologie-havo-2024-i-quinoa-context5.png$$,
   $$Anouk moet er als veganist op letten dat haar voeding voldoende eiwitrijk is. Quinoa is een goede bron van plantaardige eiwitten, omdat het alle essentiële aminozuren bevat.$$, 'inline'),
  ('db304fa6-1c8c-429a-99c2-8aaca603cc3f', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$bouwstoffen voor eiwitten$$,
   $$biologie-havo-2024-i-quinoa-context6.png$$,
   $$De quinoaplant neemt bepaalde bouwstoffen op uit het milieu voor de productie van eiwitten.$$, 'inline'),
  ('49ca1b43-ff88-47f1-ad70-1cb3599b6d74', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$vlinderbloemige planten vooraf; vier processen uit de stikstofkringloop$$,
   $$biologie-havo-2024-i-quinoa-context7.png$$,
   $$In het jaar voordat Anouk een akker gaat gebruiken voor de teelt van quinoa, laat ze er vlinderbloemige planten op groeien. Vlinderbloemige planten bezitten wortelknolletjes waarin knolletjesbacteriën leven. Door deze planten onder te ploegen, komt er uiteindelijk meer NO₃⁻ in de bodem. Vier processen uit de stikstofkringloop zijn:
1 ammonificatie door rottingsbacteriën
2 nitrificatie door nitrietbacteriën en nitraatbacteriën
3 stikstofassimilatie door vlinderbloemige planten
4 stikstoffixatie door knolletjesbacteriën$$, 'inline'),
  ('07e8a9fb-7821-4a47-86c1-5c2dab2f8635', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$snelle toename van de biomassa van quinoa$$,
   $$biologie-havo-2024-i-quinoa-context8.png$$,
   $$Anouk zaait de quinoa in maart. Nadat de zaden gekiemd zijn, groeien de planten goed. De biomassa van quinoaplanten kan snel toenemen: in vijf maanden groeit er uit een zaadje een forse plant van 1 tot 1,5 meter hoogte.$$, 'inline'),
  ('e6097eb5-b1ba-46d3-a597-361a7ecebf52', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$bloemenstrook tussen akker en sloot$$,
   $$biologie-havo-2024-i-quinoa-context9.png$$,
   $$Naast de quinoa-akker ligt een sloot. Anouk zaait tussen de akker en de sloot een zes meter brede strook in met inheemse wilde bloemen. De strook vergroot de biodiversiteit en kan tegengaan dat er te veel meststoffen vanuit de akker in het water terechtkomen.$$, 'inline'),
  ('b8b16c33-6b35-4b1f-a05c-f4eeb3a71fd6', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$verzilting van landbouwgronden$$,
   $$biologie-havo-2024-i-quinoa-context10.png$$,
   $$Steeds meer landbouwgronden verzilten: het grondwater wordt zouter door binnendringend zeewater. Ook de akkerbouwgrond van Anouk verzilt langzaam. De meeste landbouwgewassen kunnen daar niet goed tegen.$$, 'inline'),
  ('efa3f2e6-70bd-46bf-b6fc-86250cad4f88', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$kader: opslag van zout-ionen in zoutblazen (afbeelding 2); drie uitspraken$$,
   $$biologie-havo-2024-i-quinoa-context11.png$$,
   $$Quinoa is zouttolerant omdat het veel meer zout-ionen zoals Na⁺ en Cl⁻ opneemt dan andere landbouwgewassen. Deze zout-ionen worden na opname in de wortel via de vaatbundels naar de bladeren vervoerd. Daar worden ze opgeslagen in gespecialiseerde epidermiscellen die een uitstulping hebben: de zoutblaas (afbeelding 2). In die zoutblaas bevindt zich een vacuole waar zout-ionen in hoge concentraties kunnen worden opgeslagen.
afbeelding 2: tekening van een doorsnede van een quinoablad met vacuole, zoutblaas, epidermis en vaatbundel aangegeven
Over de opslag van zout-ionen in de epidermiscellen van quinoa worden de volgende uitspraken gedaan:
1 Door de opslag van zout-ionen wordt de vacuole hypotoon ten opzichte van de rest van de cel.
2 De opname van zout-ionen in de vacuole in een zoutblaas verloopt via membraaneiwitten.
3 De opname van zout-ionen in de vacuolen van de zoutblazen kost ATP.$$, 'inline'),
  ('e1010a1d-8ab4-46bf-9e3c-8f36b05a22e9', '4dd77c7a-3c65-4de3-a75a-f61ea7d215ba', $$chicha maken met melkzuurbacteriën$$,
   $$biologie-havo-2024-i-quinoa-context12.png$$,
   $$In Peru wordt van quinoa het drankje chicha gemaakt. Anouk wil dit ook proberen. Ze vermaalt quinoazaden, voegt water toe en steriliseert het mengsel door het tien minuten te verhitten tot 95 °C. Vervolgens voegt ze er melkzuurbacteriën aan toe. Na een paar dagen is de chicha klaar. Het melkzuur geeft het drankje een lichtzure, frisse smaak.$$, 'inline');

