  ('8cb1a447-4336-45b6-bfe9-ce155450cd5a', 'cd9f4c1c-7a5c-40ca-9a5d-7e0931a07fca', 1,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
